"""Render eval/results.json and eval/outputs.jsonl into eval/results.md."""
import json, collections
R = json.load(open("eval/results.json")); O = [json.loads(l) for l in open("eval/outputs.jsonl")]
b, f = R["base"], R["finetuned"]
pct = lambda x: f"{100*x:.1f}%"
rows = [("Checker pass rate (all 8 rules)", pct(b["pass_rate"]), pct(f["pass_rate"]))]
rows += [(f"  rule: {k}", pct(b["per_rule"][k]), pct(f["per_rule"][k])) for k in b["per_rule"]]
rows += [("Avg words per reply", f"{b['avg_words']:.1f}", f"{f['avg_words']:.1f}"),
         ("AI-tic hits per 100 replies", f"{b['ai_tics_per_100']:.1f}", f"{f['ai_tics_per_100']:.1f}"),
         (f"Pidgin judged correct (n={b['pidgin_n']})", pct(b["pidgin_correct_rate"]), pct(f["pidgin_correct_rate"])),
         ("Latency per reply, mean / median (s)", f"{b['latency_s_mean']:.2f} / {b['latency_s_median']:.2f}", f"{f['latency_s_mean']:.2f} / {f['latency_s_median']:.2f}"),
         ("Avg completion tokens", f"{b['avg_completion_tokens']:.1f}", f"{f['avg_completion_tokens']:.1f}"),
         ("Est. cost per reply (USD)", f"${b['cost_usd_per_reply']:.6f}", f"${f['cost_usd_per_reply']:.6f}")]
by_lang = collections.Counter((x["language"], x["pairwise"]["winner"]) for x in O)
P = R["pairwise"]
md = [f"# Eval: base Qwen3-8B vs Sloth Butler LoRA\n",
      f"Test set: {R['n_test']} held-out requests (`data/test.jsonl`), never used in training. Same system prompt, renderer (`qwen3_disable_thinking`), temperature {R['temperature']}, sampling seed {R['seed']}.",
      f"Checkpoint: `{R['checkpoint']}`. Judge: {R['judge']}, temperature 0.\n",
      "| Metric | Base | Fine-tuned |", "|---|---|---|"] + [f"| {a} | {x} | {y} |" for a, x, y in rows]
md += ["", f"## Blind pairwise preference (\"which would you actually send?\")\n",
       f"Reply order randomized per item (seed {R['seed']}). Fine-tuned preferred **{P['finetuned_wins']}/{P['n']}**, base {P['base_wins']}/{P['n']}.\n",
       "| Language | Fine-tuned wins | Base wins |", "|---|---|---|"]
for lang in ["English", "Nigerian Pidgin"]:
    md.append(f"| {lang} | {by_lang[(lang,'finetuned')]} | {by_lang[(lang,'base')]} |")
md += ["", "Cost is estimated from token counts at Tinker list prices for Qwen3-8B (prefill $0.195/M, sample $0.60/M, as of 2026-10-19); it is not read from a bill. Latency is wall-clock time of one `sample` call from this machine, including network, with 8 concurrent requests.\n",
       "## Examples\n"]
for i in [196, 135, 262]:
    x = next(o for o in O if o["id"] == i)
    md += [f"### {x['category']} ({x['style']}, {x['language']})\n", "Request:\n", "> " + x["request"].replace("\n", "\n> ") + "\n",
           f"Base (checker {'pass' if x['base']['check']['pass'] else 'fail: ' + ', '.join(k for k,v in x['base']['check']['rules'].items() if not v)}):\n",
           "> " + x["base"]["reply"].replace("\n", "\n> ") + "\n",
           f"Fine-tuned (checker {'pass' if x['finetuned']['check']['pass'] else 'fail'}):\n", "> " + x["finetuned"]["reply"].replace("\n", "\n> ") + "\n"]
md += ["## What still fails\n",
"- English quality is not better by judge preference. On English items the judge preferred the base model 20 to 16. The fine-tune is shorter and more uniform; the judge often rewarded the base model's extra warmth and context. Most of the pairwise win comes from Pidgin (22 to 2).",
"- Replies are formulaic: almost always \"I can't X. I can Y.\" This passes the checker but reads flat, especially for the `soft` style.",
"- Some counter-offers do not make sense: offering to bring dessert to a potluck three days after it happened, offering a gift \"on the day of the party\" after declining the party, offering a partial payment on a debt the user owes.",
"- The fine-tune sometimes adds \"Sorry for any inconvenience\", a corporate phrase not on the tic list.",
"- `maybe-later` style fails most often (style_match 85%): the model gives a date for the counter-offer but does not frame it as revisiting the request.",
"- The checker is regex-based. It has false positives (one fine-tune reply was flagged as a false excuse because the request names \"Toronto General Hospital\") and false negatives (it cannot tell whether an offer is sensible). Treat its numbers as a lower bound on rule-following, not a quality score.",
"- The judge is a single model (gpt-oss-120b), which is also the teacher that wrote the training data. That can bias the judge toward the fine-tune's style. No human rating has been done yet.",
"- Pidgin correctness is judged by the same LLM, not by native speakers. n=24.",
"- Test requests were generated by the same teacher as training requests, so they are in-distribution. Real user messages may be harder.",
"- Single run, single seed. No confidence intervals."]
open("eval/results.md", "w").write("\n".join(md) + "\n")
